(() => {
  const STORE = 'veylo-intentions-v1';
  const PREFS = 'veylo-preferences-v1';
  const today = new Date();
  const iso = (date) => new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  const addDays = (date, n) => { const d = new Date(date); d.setDate(d.getDate() + n); return d; };
  const uid = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  const seed = [];
  let items = loadItems();
  let prefs = loadPrefs();
  let activeView = 'space';
  let activeFilter = 'all';
  let activePeriod = 'week';
  let weekOffset = 0;
  let toastTimer;
  let recognizing;
  let googleAccessToken='';
  let googleTokenExpiresAt=0;
  let googleClientId='';
  let googleBusyWindows=[];
  let storageIssue=false;
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const esc = (s='') => String(s).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const loadItems = () => { try { const saved=JSON.parse(localStorage.getItem(STORE)); return Array.isArray(saved)?saved:structuredClone(seed); } catch { storageIssue=true;return structuredClone(seed); } };
  const loadPrefs = () => { try { return {...{reduceMotion:false,suggestions:true,nudgeLimit:2},...JSON.parse(localStorage.getItem(PREFS)||'{}')}; } catch { return {reduceMotion:false,suggestions:true,nudgeLimit:2}; } };
  try { googleClientId=localStorage.getItem('veylo-google-client-id')||''; } catch {}
  const persist = () => { try { const value=JSON.stringify(items);localStorage.setItem(STORE,value);if(localStorage.getItem(STORE)!==value)throw new Error('Storage did not confirm the write');storageIssue=false;setStorageStatus(true);return true; } catch { storageIssue=true;setStorageStatus(false);toast('Veylo could not save on this device. Use a regular browser window and try again.');return false; } };
  const persistPrefs = () => { try { localStorage.setItem(PREFS, JSON.stringify(prefs));return true; } catch { toast('Preferences could not be saved on this device.');return false; } };
  const sortRecent = (a,b) => (b.updatedAt||b.createdAt).localeCompare(a.updatedAt||a.createdAt);
  const alive = () => items.filter(x=>x.status!=='archived');
  const relative = (date) => { const day=Math.round((new Date(`${date}T00:00:00`)-new Date(`${iso(today)}T00:00:00`))/86400000); if(day===0)return 'Today'; if(day===-1)return 'Yesterday'; if(day<0&&day>-7)return `${Math.abs(day)} days ago`; return new Date(`${date}T00:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'}); };
  const kindLabel = (k) => ({idea:'Idea',action:'Action',question:'Question',goal:'Goal',commitment:'Commitment',meeting:'Conversation',note:'Note',unclassified:'Unsorted'}[k]||'Thought');
  const kindGlyph = (k) => ({idea:'✳',action:'↗',question:'?',goal:'◎',commitment:'◷',meeting:'◉',note:'∙'}[k]||'✳');
  const titleFrom = (raw) => { let t=raw.trim().replace(/^(i (want|need|should|might|could|would) to|i'd like to|we should|remember to|maybe i should)\s+/i,''); t=t.replace(/[.!?]+$/,'').replace(/\s+/g,' '); if(!t)return 'A new thought'; t=t.charAt(0).toUpperCase()+t.slice(1); return t.length>64?`${t.slice(0,61).trimEnd()}…`:t; };
  const kindFrom = (raw) => { const s=raw.toLowerCase(); if(/^\s*(what|why|how|when|where|who|could|would|is it|should i)\b/.test(s))return 'question'; if(/\b(ask|call|email|send|book|schedule|talk to|meet|remind|finish|make|write|buy|prepare|visit)\b/.test(s))return /\b(talk to|meet|call|discuss)\b/.test(s)?'meeting':'action'; if(/\b(idea|imagine|explore|maybe|someday|wonder|could we)\b/.test(s))return 'idea'; if(/\b(goal|want to become|over the next|by the end)\b/.test(s))return 'goal'; if(raw.length<80&&!/[.!?]/.test(raw))return 'note'; return 'idea'; };
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
  function setStorageStatus(available){const status=$('.sync-state');if(!status)return;status.classList.toggle('error',!available);status.querySelector('span').textContent=available?'Saved on this device':'Browser storage unavailable';}
  function setGoogleUi(){const connected=Boolean(googleAccessToken&&Date.now()<googleTokenExpiresAt);const status=$('#google-status');if(status){status.classList.toggle('connected',connected);status.innerHTML=`<i></i>${connected?'Connected for this session':googleClientId?'Not connected · reconnect when needed':'Not configured'}`;}if($('#google-client-id'))$('#google-client-id').value=googleClientId;$('#google-connect').innerHTML=googleClientId?'<span>Connect Google Calendar</span><span class="capture-arrow">↗</span>':'<span>Save a client ID to connect</span>';$('#google-disconnect').disabled=!connected;$('#calendar-refresh').disabled=!googleClientId;}
  function loadGoogleIdentity(){if(window.google?.accounts?.oauth2)return Promise.resolve();return new Promise((resolve,reject)=>{let script=document.querySelector('script[data-google-identity]');if(!script){script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.dataset.googleIdentity='true';document.head.appendChild(script);}script.addEventListener('load',resolve,{once:true});script.addEventListener('error',()=>reject(new Error('Google sign-in could not load. Check your connection.')),{once:true});});}
  function requestGoogleAccess(){return new Promise(async(resolve,reject)=>{try{await loadGoogleIdentity();if(!googleClientId)throw new Error('Add your Google OAuth web client ID first.');const scopes=['https://www.googleapis.com/auth/calendar.freebusy','https://www.googleapis.com/auth/calendar.events.owned'];const client=google.accounts.oauth2.initTokenClient({client_id:googleClientId,scope:scopes.join(' '),callback:(response)=>{if(response.error){reject(new Error(response.error_description||response.error));return;}const granted=(response.scope||'').split(/\s+/);if(!scopes.every(scope=>granted.includes(scope))){reject(new Error('Google Calendar access was not fully approved.'));return;}googleAccessToken=response.access_token;googleTokenExpiresAt=Date.now()+Number(response.expires_in||3600)*1000;setGoogleUi();resolve(googleAccessToken);},error_callback:(error)=>reject(new Error(error.message||'Google authorization was closed.'))});client.requestAccessToken({prompt:googleAccessToken?'':'consent'});}catch(error){reject(error);}});}
  async function ensureGoogleAccess(){if(googleAccessToken&&Date.now()<googleTokenExpiresAt-60000)return googleAccessToken;return requestGoogleAccess();}
  async function calendarRequest(path,options={}){const token=await ensureGoogleAccess();const response=await fetch(`https://www.googleapis.com/calendar/v3${path}`,{...options,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json',...(options.headers||{})}});if(!response.ok){let message=`Google Calendar returned ${response.status}`;try{const payload=await response.json();message=payload.error?.message||message;}catch{}throw new Error(message);}return response.status===204?null:response.json();}
  async function connectGoogleCalendar(){const supplied=$('#google-client-id').value.trim();if(supplied!==googleClientId){googleClientId=supplied;try{localStorage.setItem('veylo-google-client-id',googleClientId);}catch{toast('Could not save the client ID on this device.');return;}}if(!googleClientId){toast('Add your Google OAuth web client ID first.');return;}try{await requestGoogleAccess();renderTime();toast('Google Calendar connected for this session.');}catch(error){toast(error.message||'Google Calendar could not connect.');}}
  async function refreshAvailability(){const button=$('#calendar-refresh');button.disabled=true;button.textContent='Checking…';try{const days=weekDates();const start=days[0],end=addDays(days[6],1);const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';const result=await calendarRequest('/freeBusy',{method:'POST',body:JSON.stringify({timeMin:start.toISOString(),timeMax:end.toISOString(),timeZone:timezone,items:[{id:'primary'}]})});googleBusyWindows=result.calendars?.primary?.busy||[];const details=googleBusyWindows.slice(0,5).map(b=>`${new Date(b.start).toLocaleString(undefined,{weekday:'short',hour:'numeric',minute:'2-digit'})}–${new Date(b.end).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}`).join('<br>');$('#availability-result').innerHTML=`This week: ${googleBusyWindows.length} busy ${googleBusyWindows.length===1?'window':'windows'} on your primary calendar.${details?`<br>${details}`:''}`;toast('Free/busy availability refreshed');}catch(error){toast(error.message||'Could not read calendar availability.');}finally{button.textContent='Check this week’s availability';button.disabled=!(googleAccessToken&&Date.now()<googleTokenExpiresAt);}}
  async function eventIdFor(blockId){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`veylo:${blockId}`));return `v${[...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,31)}`;}
  async function createCalendarEvent(intentionId,blockId){const item=items.find(x=>x.id===intentionId);const block=item?.blocks?.find(x=>x.id===blockId);if(!item||!block||block.externalEventId)return;const description=[item.intent,item.purpose?`Why it matters: ${item.purpose}`:''].filter(Boolean).join('\n\n');if(!confirm(`Add “${item.title}” to your Google Calendar on ${block.date} at ${block.time} for ${block.duration} minutes?`))return;try{const id=await eventIdFor(block.id);const zone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';const startLocal=new Date(`${block.date}T${block.time}:00`);const endLocal=new Date(startLocal.getTime()+Number(block.duration)*60000);const localStamp=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}:00`;const body={id,summary:item.title,description,start:{dateTime:localStamp(startLocal),timeZone:zone},end:{dateTime:localStamp(endLocal),timeZone:zone}};let result;try{result=await calendarRequest('/calendars/primary/events',{method:'POST',body:JSON.stringify(body)});}catch(error){if(!/409|already exists/i.test(error.message))throw error;result=await calendarRequest(`/calendars/primary/events/${id}`);}block.externalEventId=result.id;block.externalLink=result.htmlLink||'';block.syncState='synced';if(!persist()){block.externalEventId=result.id;toast('Event is in Google Calendar, but its link could not be saved here.');}else toast('Added to Google Calendar.');renderAll();}catch(error){toast(error.message||'Could not add the event to Google Calendar.');}}
  function disconnectGoogleCalendar(){if(!googleAccessToken){toast('Google Calendar is not connected.');return;}const token=googleAccessToken;googleAccessToken='';googleTokenExpiresAt=0;googleBusyWindows=[];window.google?.accounts?.oauth2?.revoke(token,()=>{});$('#availability-result').textContent='';setGoogleUi();renderTime();toast('Google Calendar disconnected from this session.');}
  function decorateTimeView(){const list=$('#schedule-list');if(list){for(const row of $$('.schedule-item',list)){const remove=row.querySelector('[data-remove-block]');if(!remove)continue;const item=items.find(x=>x.id===remove.dataset.removeBlock);const block=item?.blocks?.find(x=>x.id===remove.dataset.block);if(!block)continue;const copy=row.querySelector('.schedule-copy');if(block.externalEventId){const tag=document.createElement(block.externalLink?'a':'span');tag.className='calendar-added';tag.textContent='✓ In Google Calendar';if(block.externalLink){tag.href=block.externalLink;tag.target='_blank';tag.rel='noopener noreferrer';}copy.append(tag);}else{const button=document.createElement('button');button.className='calendar-add';button.dataset.calendarCreate=`${item.id}:${block.id}`;button.textContent=googleClientId?'Add to calendar':'Connect calendar to add';button.disabled=!googleClientId;copy.append(button);}}}for(const cell of $$('.day-cell[data-day]')){const busy=googleBusyWindows.filter(w=>iso(new Date(w.start))===cell.dataset.day||iso(new Date(new Date(w.end).getTime()-1))===cell.dataset.day).length;if(busy){cell.classList.add('has-calendar-busy');cell.title+=` · ${busy} Google Calendar busy window${busy===1?'':'s'}`;const label=document.createElement('span');label.className='busy-count';label.textContent=`${busy} busy`;cell.append(label);}}}
  function switchView(view){activeView=view;$$('.view').forEach(el=>el.classList.toggle('active',el.id===`view-${view}`));$$('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const names={space:'Living space',explore:'Explore',align:'Align',time:'Time',suggestions:'Suggestions',connections:'Connections'};$('#crumb-current').textContent=names[view]||'Living space';if(view==='time')renderTime();if(view==='align')renderAlign();if(view==='suggestions')renderSuggestions();if(view==='explore')renderExplore();if(view==='connections')setGoogleUi();window.scrollTo({top:0,behavior:prefs.reduceMotion?'instant':'smooth'});}
  function card(item){return `<button class="intention-card" data-open="${esc(item.id)}"><span class="card-top"><span class="kind-chip"><i></i>${kindLabel(item.kind)}</span><span class="card-more">···</span></span><h3>${esc(item.title)}</h3><p>${esc(item.intent||item.rawCapture||item.raw)}</p><span class="card-bottom"><span class="card-purpose">${item.purpose?`◎ ${esc(item.purpose)}`:'○ Still taking shape'}</span><span>${relative(item.updatedAt||item.createdAt)}</span></span></button>`;}
  function empty(title,body,glyph='✳'){return `<div class="empty-state"><div class="empty-symbol">${glyph}</div><h3>${title}</h3><p>${body}</p></div>`;}
  function renderHome(){const data=alive().sort(sortRecent);$('#recent-grid').innerHTML=data.length?data.slice(0,3).map(card).join(''):empty('A clear little space','Save a thought above when one comes to mind.');$('#explore-count').textContent=data.length;$('#count-all').textContent=data.length;}
  function renderExplore(){let data=alive().sort(sortRecent);if(activeFilter!=='all')data=data.filter(i=>i.kind===activeFilter);const term=$('#search-input').value.trim().toLowerCase();if(term)data=data.filter(i=>[i.title,i.raw,i.intent,i.purpose].join(' ').toLowerCase().includes(term));$('#explore-list').innerHTML=data.length?data.map(i=>`<article class="explore-row" tabindex="0" role="button" data-open="${esc(i.id)}"><span class="row-orb ${esc(i.kind)}">${kindGlyph(i.kind)}</span><div class="row-copy"><h3>${esc(i.title)}</h3><p>${esc(i.raw)}</p></div><div class="row-meta"><span>${kindLabel(i.kind)}</span><span>${relative(i.updatedAt||i.createdAt)}</span><span class="row-horizon">${esc(i.horizon||'Someday')}</span></div><span class="row-arrow">↗</span></article>`).join(''):empty(term?'No matching thoughts':'Nothing here yet',term?'Try a different word.':'Capture a thought and it will find its way here.');}
  function renderAlign(){const data=alive().sort(sortRecent);const groups=new Map();for(const i of data){const p=(i.purpose||'').trim();if(p){if(!groups.has(p))groups.set(p,[]);groups.get(p).push(i);}}let html='';for(const [purpose,group]of groups){html+=`<section class="purpose-section"><div class="purpose-head"><span class="purpose-icon">◎</span><h2>${esc(purpose)}</h2><span>${group.length} ${group.length===1?'intention':'intentions'}</span></div><div class="purpose-items">${group.map(i=>`<button class="purpose-item" data-open="${esc(i.id)}"><span class="tiny-orb">${kindGlyph(i.kind)}</span><span>${esc(i.title)}</span><small>${kindLabel(i.kind)}</small></button>`).join('')}</div></section>`;}const loose=data.filter(i=>!i.purpose);if(loose.length)html+=`<section class="purpose-section"><div class="purpose-head"><span class="purpose-icon">∙</span><h2>Still finding its why</h2><span>${loose.length}</span></div><div class="unanchored">${loose.length} ${loose.length===1?'thought':'thoughts'} haven’t been connected to a purpose yet.</div></section>`;$('#align-content').innerHTML=html||empty('Nothing to align yet','Once you add a purpose to a thought, related intentions will gather here.','⌘');}
  function getMonday(date){const d=new Date(date);const wd=(d.getDay()+6)%7;d.setDate(d.getDate()-wd);d.setHours(0,0,0,0);return d;}
  function weekDates(){const monday=getMonday(today);monday.setDate(monday.getDate()+weekOffset*7);return Array.from({length:7},(_,n)=>addDays(monday,n));}
  function allBlocks(){return alive().flatMap(i=>(i.blocks||[]).map(b=>({...b,item:i}))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));}
  function renderTime(){const dates=weekDates();const first=dates[0],last=dates[6];$('#week-label').textContent=`${first.toLocaleDateString(undefined,{month:'short',day:'numeric'})} – ${last.toLocaleDateString(undefined,{month:'short',day:'numeric'})}`;const blocks=allBlocks();if(activePeriod==='week'){$('#week-overview').className='week-overview';$('#week-overview').innerHTML=dates.map(d=>{const day=iso(d);const n=blocks.filter(b=>b.date===day).length;const t=iso(d)===iso(today);return `<div class="day-cell ${t?'today':''}" data-day="${day}" title="${n?`${n} planned block${n>1?'s':''}`:'Choose to plan time'}"><span class="day-name">${d.toLocaleDateString(undefined,{weekday:'short'})}</span><span class="day-date">${d.getDate()}</span><span class="day-capacity"><i style="width:${Math.min(n*35,100)}%"></i></span></div>`}).join('');$('#week-overview').onclick=(e)=>{const cell=e.target.closest('[data-day]');if(cell)planBlock(null,cell.dataset.day);};}else if(activePeriod==='year'){const months=Array.from({length:12},(_,i)=>new Date(today.getFullYear(),i,1));$('#week-overview').className='year-overview';$('#week-overview').innerHTML=months.map(d=>`<button class="month-tile" data-month="${d.getMonth()}"><span>${d.toLocaleDateString(undefined,{month:'long'})}</span><small>${blocks.filter(b=>new Date(`${b.date}T00:00:00`).getMonth()===d.getMonth()).length} planned moments</small></button>`).join('');$('#week-overview').onclick=e=>{const b=e.target.closest('[data-month]');if(b){activePeriod='month';$$('.time-view').forEach(x=>x.classList.toggle('active',x.dataset.period==='month'));weekOffset=0;renderTime(new Date(today.getFullYear(),Number(b.dataset.month),1));}};}else{let shown=window._veyloMonth||new Date(today.getFullYear(),today.getMonth()+weekOffset,1);const start=new Date(shown.getFullYear(),shown.getMonth(),1);const begin=getMonday(start);const days=Array.from({length:42},(_,i)=>addDays(begin,i));$('#week-label').textContent=shown.toLocaleDateString(undefined,{month:'long',year:'numeric'});$('#week-overview').className='month-overview';$('#week-overview').innerHTML=days.map(d=>`<div class="month-day ${d.getMonth()!==shown.getMonth()?'muted':''} ${blocks.some(b=>b.date===iso(d))?'has-block':''}" data-day="${iso(d)}">${d.getDate()}${blocks.some(b=>b.date===iso(d))?'<span>planned</span>':''}</div>`).join('');}
    const chosen=new Set(dates.map(iso));const visible=blocks.filter(b=>activePeriod==='week'?chosen.has(b.date):activePeriod==='month'?new Date(`${b.date}T00:00:00`).getMonth()===(window._veyloMonth||new Date(today.getFullYear(),today.getMonth()+weekOffset,1)).getMonth():new Date(`${b.date}T00:00:00`).getFullYear()===today.getFullYear());$('#schedule-subtitle').textContent=visible.length?`${visible.length} planned ${visible.length===1?'moment':'moments'} this ${activePeriod}.`:"No blocks planned yet. A gentle start is enough.";$('#schedule-list').innerHTML=visible.length?visible.map(b=>`<div class="schedule-item"><span class="schedule-time">${b.date===iso(today)?'Today':new Date(`${b.date}T00:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}<br>${esc(b.time)}</span><span class="schedule-marker"></span><div class="schedule-copy"><b>${esc(b.item.title)}</b><small>${b.duration} min · planned by you</small></div><button class="schedule-remove" data-remove-block="${esc(b.item.id)}" data-block="${esc(b.id)}" aria-label="Remove time block">×</button></div>`).join(''):'<div class="schedule-empty">Nothing set aside here yet.</div>';
    const unscheduled=alive().filter(i=>i.status!=='completed'&&!(i.blocks||[]).length).sort(sortRecent);$('#unscheduled-list').innerHTML=unscheduled.slice(0,5).map(i=>`<div class="unscheduled-item"><button data-open="${esc(i.id)}">${esc(i.title)}</button><button class="quick-plan" data-plan="${esc(i.id)}">Find time</button></div>`).join('')||'<div class="schedule-empty">Everything has a little room.</div>';}
  function renderSuggestions(){if(!prefs.suggestions){$('#suggestion-list').innerHTML=empty('Suggestions are paused','You can turn them back on in preferences.','◌');return;}const itemsToSuggest=alive().filter(i=>i.status!=='completed'&&!(i.blocks||[]).length&&!i.suggestionDismissed&&(!i.snoozedUntil||i.snoozedUntil<=iso(today))).sort((a,b)=>score(b)-score(a)).slice(0,3);const copy=(i)=>{let rationale=i.purpose?`You connected this to “${i.purpose}.”`:'You saved this thought and haven’t made room for it yet.';if(i.horizon&&i.horizon!=='Someday')rationale+=` You marked the horizon as ${i.horizon.toLowerCase()}.`;return rationale;};$('#suggestion-list').innerHTML=itemsToSuggest.length?itemsToSuggest.map(i=>`<article class="suggestion-card"><div class="suggestion-top"><span class="suggestion-label">✧ A possibility</span><span class="suggestion-confidence">Based on your own notes</span></div><h3>${esc(i.kind==='question'?'Spend a few minutes with this question':`Make a little room for “${i.title}”`)}</h3><p>${esc(i.intent||i.raw)}</p><div class="suggestion-reason"><span>Why this came up</span><span>${esc(copy(i))}</span></div><div class="suggestion-actions"><button data-plan="${esc(i.id)}">Find time</button><button data-snooze="${esc(i.id)}">Later</button><button data-dismiss="${esc(i.id)}">Dismiss</button><button data-open="${esc(i.id)}">Open thought</button></div></article>`).join(''):'<div class="suggestion-empty">Nothing needs a nudge right now. Let the quiet be useful.</div>';}
  function score(i){return (i.purpose?0.3:0)+(i.horizon&&i.horizon!=='Someday'?0.25:0)+(['ready','planned'].includes(i.status)?0.22:0)+(i.kind==='action'?0.16:0)+0.08;}
  const renderTimeBase=renderTime;renderTime=function(...args){renderTimeBase(...args);decorateTimeView();};
  function openDetail(id){const i=items.find(x=>x.id===id);if(!i)return;$('#detail-content').innerHTML=`<div class="detail-inner"><div class="detail-kind"><i></i>${kindLabel(i.kind)} <span>·</span> saved ${relative(i.createdAt)}</div><input class="detail-title-input" id="edit-title" value="${esc(i.title)}" aria-label="Title"><div class="detail-raw">“${esc(i.raw)}”</div><div class="detail-fields"><div class="detail-field"><label for="edit-intent">What do you want to do?</label><textarea id="edit-intent" placeholder="You can leave this blank">${esc(i.intent||'')}</textarea></div><div class="detail-field"><label for="edit-purpose">Why does it matter to you?</label><input id="edit-purpose" value="${esc(i.purpose||'')}" placeholder="A purpose you care about"></div><div class="detail-field"><label for="edit-outcome">What would a good outcome look like?</label><textarea id="edit-outcome" placeholder="No need to have it figured out">${esc(i.desiredOutcome||'')}</textarea></div><div class="detail-field"><label for="edit-plan">A first step or rough plan</label><textarea id="edit-plan" placeholder="A few loose thoughts are enough">${esc(i.roughPlan||'')}</textarea></div><div class="detail-field detail-selects"><label for="edit-kind">Type &amp; horizon</label><div style="display:flex;gap:8px"><select id="edit-kind">${['idea','action','question','goal','commitment','meeting','note','unclassified'].map(k=>`<option value="${k}" ${k===i.kind?'selected':''}>${kindLabel(k)}</option>`).join('')}</select><select id="edit-horizon">${['Someday','Today','This week','Next week','This month'].map(h=>`<option ${h===i.horizon?'selected':''}>${h}</option>`).join('')}</select></div></div></div><div class="detail-bottom"><span class="detail-meta">${i.blocks?.length?`${i.blocks.length} planned moment${i.blocks.length>1?'s':''}`:`${i.status==='completed'?'Completed':i.status==='exploring'?'Taking shape':'Still open'}`}</span><div class="detail-actions"><button class="complete-detail" data-complete="${esc(i.id)}">${i.status==='completed'?'Reopen':'Mark complete'}</button><button class="save-detail" data-save-detail="${esc(i.id)}">Save changes</button></div></div></div>`;$('#detail-dialog').showModal();}
  function saveDetail(id){const i=items.find(x=>x.id===id);if(!i)return;const previous=structuredClone(i);i.title=$('#edit-title').value.trim()||titleFrom(i.raw);i.intent=$('#edit-intent').value.trim();i.purpose=$('#edit-purpose').value.trim();i.desiredOutcome=$('#edit-outcome').value.trim();i.roughPlan=$('#edit-plan').value.trim();i.kind=$('#edit-kind').value;i.horizon=$('#edit-horizon').value;i.updatedAt=iso(today);if(!persist()){Object.assign(i,previous);return;}$('#detail-dialog').close();renderAll();toast('Thought updated');}
  function saveCapture(){const input=$('#capture-input');const raw=input.value.trim();if(!raw){input.focus();return;}const item={id:uid(),raw,title:titleFrom(raw),kind:kindFrom(raw),intent:'',purpose:'',desiredOutcome:'',roughPlan:'',horizon:/next week/i.test(raw)?'Next week':/today|tomorrow/i.test(raw)?'This week':'Someday',status:'captured',createdAt:iso(today),updatedAt:iso(today),effort:25,related:[],blocks:[]};items.unshift(item);if(!persist()){items=items.filter(x=>x.id!==item.id);return;}input.value='';renderAll();toast('Kept. You can shape it whenever you’re ready.');}
  function planBlock(id,day){const candidates=alive().filter(x=>x.status!=='completed');if(!candidates.length){toast('Add an intention before planning time.');return;}$('#schedule-intention').innerHTML=candidates.map(x=>`<option value="${esc(x.id)}" ${x.id===id?'selected':''}>${esc(x.title)}</option>`).join('');$('#schedule-date').value=day||iso(addDays(today,1));$('#schedule-time').value='10:00';$('#schedule-dialog').showModal();}
  function saveSchedule(){const i=items.find(x=>x.id===$('#schedule-intention').value);const date=$('#schedule-date').value;const time=$('#schedule-time').value;const duration=Number($('#schedule-duration').value);if(!i||!date||!time){toast('Choose an intention, date, and time.');return;}const previous={blocks:structuredClone(i.blocks||[]),status:i.status,updatedAt:i.updatedAt};i.blocks=i.blocks||[];i.blocks.push({id:uid(),date,time,duration});i.status='planned';i.updatedAt=iso(today);if(!persist()){Object.assign(i,previous);return;}$('#schedule-dialog').close();renderAll();toast('Time set aside.');}
  function removeBlock(id,blockId){const i=items.find(x=>x.id===id);if(!i)return;const previous={blocks:structuredClone(i.blocks||[]),status:i.status};i.blocks=(i.blocks||[]).filter(b=>b.id!==blockId);if(!i.blocks.length&&i.status==='planned')i.status='ready';if(!persist()){Object.assign(i,previous);return;}renderTime();toast('Time block removed');}
  function renderAll(){renderHome();if(activeView==='explore')renderExplore();if(activeView==='align')renderAlign();if(activeView==='time')renderTime();if(activeView==='suggestions')renderSuggestions();}
  function setFilter(filter){activeFilter=filter;$$('.filter-pill').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));renderExplore();}
  document.addEventListener('click',(e)=>{const nav=e.target.closest('[data-view]');if(nav){switchView(nav.dataset.view);return;}const opener=e.target.closest('[data-open]');if(opener){openDetail(opener.dataset.open);return;}const saver=e.target.closest('[data-save-detail]');if(saver){saveDetail(saver.dataset.saveDetail);return;}const complete=e.target.closest('[data-complete]');if(complete){const i=items.find(x=>x.id===complete.dataset.complete);if(i){i.status=i.status==='completed'?'ready':'completed';i.updatedAt=iso(today);persist();$('#detail-dialog').close();renderAll();toast(i.status==='completed'?'Marked complete':'Back in your space');}return;}const plan=e.target.closest('[data-plan]');if(plan){planBlock(plan.dataset.plan);return;}const dismiss=e.target.closest('[data-dismiss]');if(dismiss){const i=items.find(x=>x.id===dismiss.dataset.dismiss);if(i)i.suggestionDismissed=true;persist();renderAll();toast('Suggestion dismissed · thought kept in your space');return;}const snooze=e.target.closest('[data-snooze]');if(snooze){const i=items.find(x=>x.id===snooze.dataset.snooze);if(i){i.snoozedUntil=iso(addDays(today,3));persist();renderSuggestions();toast('We’ll leave this one quiet for now');}return;}const rm=e.target.closest('[data-remove-block]');if(rm){removeBlock(rm.dataset.removeBlock,rm.dataset.block);return;}const monthDay=e.target.closest('.month-day[data-day]');if(monthDay){planBlock(null,monthDay.dataset.day);return;}const pill=e.target.closest('[data-filter]');if(pill){setFilter(pill.dataset.filter);return;}const period=e.target.closest('[data-period]');if(period){activePeriod=period.dataset.period;if(activePeriod==='month')window._veyloMonth=new Date(today.getFullYear(),today.getMonth()+weekOffset,1);$$('.time-view').forEach(x=>x.classList.toggle('active',x===period));renderTime();return;}});
  $('#capture-submit').addEventListener('click',saveCapture);$('#capture-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();saveCapture();}});$('#view-all').addEventListener('click',()=>switchView('explore'));$('#settings-open').addEventListener('click',()=>$('#settings-dialog').showModal());$('#help-button').addEventListener('click',()=>toast('Capture first. Give a thought its shape when you’re ready.'));$('#add-purpose').addEventListener('click',()=>{const open=alive().filter(i=>i.status!=='completed');if(!open.length){toast('Save an intention first.');return;}const chosen=open.find(i=>!i.purpose)||open[0];openDetail(chosen.id);setTimeout(()=>$('#edit-purpose')?.focus(),80);toast('Add a purpose to an intention. Related thoughts gather here.');});$('#plan-time').addEventListener('click',()=>planBlock(null));$('#week-prev').addEventListener('click',()=>{if(activePeriod==='month'){window._veyloMonth=new Date((window._veyloMonth||today).getFullYear(),(window._veyloMonth||today).getMonth()-1,1);}else weekOffset--;renderTime();});$('#week-next').addEventListener('click',()=>{if(activePeriod==='month'){window._veyloMonth=new Date((window._veyloMonth||today).getFullYear(),(window._veyloMonth||today).getMonth()+1,1);}else weekOffset++;renderTime();});$('#search-toggle').addEventListener('click',()=>{const i=$('#search-input');i.classList.toggle('hidden');if(!i.classList.contains('hidden'))i.focus();});$('#search-input').addEventListener('input',renderExplore);$('#suggestion-settings').addEventListener('click',()=>$('#settings-dialog').showModal());$('#reduced-motion').checked=prefs.reduceMotion;$('#suggestions-enabled').checked=prefs.suggestions;$('#nudge-limit').value=String(prefs.nudgeLimit);$('#reduced-motion').addEventListener('change',e=>{prefs.reduceMotion=e.target.checked;document.body.classList.toggle('reduce-motion',prefs.reduceMotion);persistPrefs();});$('#suggestions-enabled').addEventListener('change',e=>{prefs.suggestions=e.target.checked;persistPrefs();renderSuggestions();});$('#nudge-limit').addEventListener('change',e=>{prefs.nudgeLimit=Number(e.target.value);persistPrefs();});$('#export-data').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),intentions:items},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='veylo-thoughts.json';a.click();URL.revokeObjectURL(a.href);toast('Your export is ready');});$('#clear-data').addEventListener('click',()=>{if(confirm('Clear all intentions from this browser? This cannot be undone.')){items=[];persist();renderAll();$('#settings-dialog').close();toast('This space is clear');}});
  $('#mic-button').addEventListener('click',()=>{const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Voice capture isn’t available in this browser. You can type your thought instead.');return;}if(recognizing){recognizing.stop();return;}recognizing=new SpeechRecognition();recognizing.lang=navigator.language||'en-US';recognizing.interimResults=true;recognizing.continuous=false;const mic=$('#mic-button');mic.classList.add('recording');recognizing.onresult=(event)=>{const text=Array.from(event.results).map(r=>r[0].transcript).join(' ');$('#capture-input').value=text;};recognizing.onerror=()=>toast('Couldn’t hear that. Try again or type your thought.');recognizing.onend=()=>{mic.classList.remove('recording');recognizing=null;};recognizing.start();toast('Listening. Tap the mic again when you’re done.');});$('#mobile-capture-open').addEventListener('click',()=>{window.scrollTo({top:0,behavior:'smooth'});$('#capture-input').focus();});
  $('#schedule-save').addEventListener('click',saveSchedule);$('#schedule-cancel').addEventListener('click',()=>$('#schedule-dialog').close());document.addEventListener('click',e=>{const month=e.target.closest('.month-tile');if(month)window._veyloMonth=new Date(today.getFullYear(),Number(month.dataset.month),1);},true);
  $('#save-google-client').addEventListener('click',()=>{googleClientId=$('#google-client-id').value.trim();try{localStorage.setItem('veylo-google-client-id',googleClientId);setGoogleUi();toast(googleClientId?'Google client ID saved on this device.':'Client ID removed.');}catch{toast('Could not save the client ID on this device.');}});$('#google-connect').addEventListener('click',connectGoogleCalendar);$('#google-disconnect').addEventListener('click',disconnectGoogleCalendar);$('#calendar-refresh').addEventListener('click',refreshAvailability);document.addEventListener('click',e=>{const button=e.target.closest('[data-calendar-create]');if(button){const [intentionId,blockId]=button.dataset.calendarCreate.split(':');createCalendarEvent(intentionId,blockId);}});
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(activeView!=='explore')switchView('explore');$('#search-input').classList.remove('hidden');$('#search-input').focus();}if(e.key==='Escape'){if($('#detail-dialog').open)$('#detail-dialog').close();if($('#settings-dialog').open)$('#settings-dialog').close();if($('#schedule-dialog').open)$('#schedule-dialog').close();}if(e.key==='Enter'&&e.target.matches('.explore-row'))openDetail(e.target.dataset.open);});
  $('#today-label').textContent=today.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();document.body.classList.toggle('reduce-motion',prefs.reduceMotion);setStorageStatus(!storageIssue);setGoogleUi();renderAll();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('/sw.js').catch(()=>{});
})();
